use std::{fs,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn main(){let p="/tmp/zopro-poseidon-frontier/analysis.json";let bytes=fs::read(p).unwrap();let a:Value=serde_json::from_slice(&bytes).unwrap();let mut rows=BTreeMap::new();for(name,case)in a["cases"].as_object().unwrap(){if case["workers"]!=32{continue;}let records=case["plans"][0]["records"].as_array().unwrap();let peak=records.iter().filter(|s|s["scope"]=="epoch").map(|s|s["max_abstract_frontier"][3].as_u64().unwrap()).max().unwrap();if case["shape"]!="merge-54x1"{assert!(peak<=64);}rows.insert(name,json!({"shape":case["shape"],"width3_pure_task_upper_bound":peak,"previous_grouping_requires_more_than":64,"could_pass_previous32worker_guard":peak>64}));}assert_eq!(rows.len(),9);fs::write("/tmp/zopro-poseidon-fused-dot/context-audit.json",serde_json::to_vec_pretty(&json!({"source":p,"source_sha256":format!("{:x}",Sha256::digest(bytes)),"cases":rows,"proof":"Every wholly-width3 eligible task begins with a width3 hash, so eligible count is bounded above by the depth0 width3 frontier, which is bounded by its maximum over all depths. Earlier guard requires eligible>2workers=64. All original8shape maxima<=52, so that guard cannot enable grouped batching there at32workers.","new_speed_claim":false,"new_proofs":0,"next_prior":6946})).unwrap()).unwrap();println!("Verified previous32worker guard ineligible for all8originalshapes; scalar fusion has no such restriction");}
